from pathlib import Path
import json,hashlib,subprocess,shutil
import numpy as np,pandas as pd
R=Path(__file__).resolve().parent;genes=pd.read_csv(R/'signature_30_genes.csv').gene.tolist();raw=pd.read_csv(R/'selected_patient_31_gene_counts.csv',index_col=0);score=pd.read_csv(R/'patient_scores.csv').set_index('patient');par=pd.read_csv(R/'bulk_score_parameters.csv').set_index('gene');X=np.log2(raw[genes].div(score.loc[raw.index,'assigned_gene_counts'],axis=0)*1e6+1);independent=np.zeros(len(X))
for g in genes:
 vals=X[g].to_numpy();m=sum(float(z) for z in vals)/len(vals);sd=(sum((float(z)-m)**2 for z in vals)/(len(vals)-1))**.5;assert np.isclose(m,par.loc[g,'bulk_training_mean_log2_CPM_plus1']) and np.isclose(sd,par.loc[g,'bulk_training_SD']);independent+=(vals-m)/sd/30
err=float(abs(independent-score.loc[X.index,'candidate30_score']).max());assert err<1e-10;cut=sorted(independent)[len(independent)//2];assert np.isclose(cut,json.loads((R/'preparation_summary.json').read_text())['score_median']);assert np.array_equal(np.where(independent>cut,'High','Low'),score.loc[X.index,'group'].to_numpy());(R/'independent_bulk_score_checks.json').write_text(json.dumps({'patients_checked':len(X),'genes_checked':30,'max_absolute_score_error':err,'global_median_grouping_checked':True,'status':'Passed'},indent=2))
repo=R/'UCSCXenaShiny_source';commit=subprocess.check_output(['git','-C',str(repo),'rev-parse','HEAD'],text=True).strip();Q=R/'source_metadata';Q.mkdir(exist_ok=True)
for src,dst in [(repo/'data/tcga_surv.rda',Q/'tcga_surv_mirror.rda'),(repo/'data-raw/raw-data-collection-and-tidying.R',Q/'UCSCXenaShiny_survival_collection.R'),(repo/'man/tcga_surv.Rd',Q/'tcga_surv_source_documentation.Rd'),(R/'cancer_types.txt.gz',Q/'GSE62944_cancer_type_sample_map.txt.gz'),(R/'TCGA_CDR_mirror_survival.csv.gz',Q/'TCGA_CDR_mirror_survival.csv.gz')]:shutil.copy2(src,dst)
provenance={'access_date':'2026-10-09','expression_url':'https://ftp.ncbi.nlm.nih.gov/geo/samples/GSM1536nnn/GSM1536837/suppl/GSM1536837_06_01_15_TCGA_24.tumor_Rsubread_FeatureCounts.txt.gz','sample_type_url':'https://ftp.ncbi.nlm.nih.gov/geo/series/GSE62nnn/GSE62944/suppl/GSE62944_06_01_15_TCGA_24_CancerType_Samples.txt.gz','expression_record':'https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE62944','survival_repository':'https://github.com/openbiox/UCSCXenaShiny','survival_commit':commit,'survival_file':'data/tcga_surv.rda','survival_origin_from_source_script':'Xena Toil TCGA_survival_data; DOI https://doi.org/10.1016/j.cell.2018.02.052','source_kind':'Public TCGA reprocessing mirror and curated clinical mirror, not fresh GDC extraction','signature_source_commit':'bdec8f03667aa755fe9303b1567cddd22ca1231c','network_limit':'Xena/GDC direct domains returned proxy403; legitimate NCBI/GitHub mirrors used'}
(R/'source_provenance.json').write_text(json.dumps(provenance,indent=2));hashes={}
for p in [R/'TCGA24_tumor_featurecounts.txt.gz',R/'cancer_types.txt.gz',repo/'data/tcga_surv.rda',Path('/workspace/codex/results/PGAM5_state_adjustment_v3/EXPLORATORY_30_gene_macrophage_program_NOT_VALIDATED.csv')]:
 h=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(4*1024**2),b''):h.update(b)
 hashes[str(p)]={'bytes':p.stat().st_size,'sha256':h.hexdigest()}
assert (R/'TCGA24_tumor_featurecounts.txt.gz').stat().st_size==307951450
(R/'input_sha256.json').write_text(json.dumps(hashes,indent=2));s=pd.read_csv(R/'survival_statistics.csv');prep=json.loads((R/'preparation_summary.json').read_text());pg=json.loads((R/'score_PGAM5_association.json').read_text());lines=['# TCGA-LIHC：30基因候选程序评分与生存的探索性分析','', '**结果：候选评分高组OS较差；PFI差异不显著。此次没有计算巨噬细胞浸润丰度，也不能据此证明PGAM5特异状态的预后作用。**','', '## 主要结果','', '| 终点 | 患者（事件） | 高组/低组患者 | 高组对低组HR（95%CI） | log-rank p | 两终点BH q |','|---|---:|---:|---|---:|---:|']
for _,t in s.iterrows():lines.append(f'| {t.endpoint} | {int(t.patients)}（{int(t.events)}） | {int(t.high_patients)}/{int(t.low_patients)} | {t.HR_high_vs_low:.3f}（{t.HR_95CI_lower:.3f}–{t.HR_95CI_upper:.3f}） | {t.logrank_p:.6g} | {t.logrank_BH_q_2_endpoints:.6g} |')
lines+=['','OS：高候选评分与较短总生存相关，在两项主要log-rank检验的BH校正后仍显著。PFI：没有发现高低组统计学差异；这不等于证明两组结局相同。HR来自未调整协变量的单变量Cox模型，不能解释为因果或独立预后效应。','', '**终点说明：可用表提供PFI（progression-free interval，无进展间期），不提供严格定义的PFS。PFI自诊断起衡量进展/复发等事件，包含TCGA-CDR规定的事件与删失规则；不能将这条曲线重命名为PFS。** 若研究方案必须使用PFS，需要另外取得定义明确的PFS时间与事件数据。','', '## 数据与评分','', f"NCBI GSE62944/GSM1536837保存的TCGA重处理FeatureCounts矩阵，共23,368基因、9,264份泛癌肿瘤RNA样本。其中LIHC374份，样本类型01原发肿瘤371份，对应371位患者，30个候选基因全部存在。此为2015年的历史重处理数据，不是当前GDC STAR矩阵。",'', f"TCGA-CDR生存信息来自UCSCXenaShiny中Xena Toil生存数据镜像（提交{commit}），其采集脚本将来源标为Liu等Cell2018，DOI:10.1016/j.cell.2018.02.052。镜像包含同一患者的正常/复发样本别名；核对所有八项终点值一致后保留原发01别名，按12字符患者ID一对一合并。369位匹配到生存表，2位未匹配。",'', '评分采用log2(CPM+1)，每个基因在全部371位患者内标准化为z分数，再对30个基因等权求平均。bulk与单细胞表达单位不同，未直接套用单细胞CP10k标准化参数。CPM分母是完整矩阵所有基因的赋值计数总和，不是仅30个基因计数。', '', f"在查看生存统计结果前，固定使用全部评分患者的中位数{prep['score_median']:.9f}：高组>中位数，低组≤中位数。原始评分队列高185、低186，两终点沿用同一阈值，没有寻找最佳生存切点。",'', 'OS分析排除8位患者（未匹配、时间缺失或非正值），保留363位；PFI排除7位，保留364位。各排除患者与原因列于endpoint_excluded_patients.csv。事件编码0=删失，1=事件，计算使用原始天数，图形用天数/30.4375显示月份。','', f"候选评分与bulk PGAM5表达的Spearman相关为{pg['Spearman_rho']:.3f}，p={pg['p']:.3g}。这只是bulk层面的弱正相关，不能建立PGAM5特异性或定位到巨噬细胞。",'', '## 图与统计复核','', '![OS KM curve](KM_OS.png)','', '![PFI KM curve](KM_PFI.png)','', '曲线含Greenwood log-log 95%置信区间、删失标记和风险人数表；风险人数为每个时间点开始时仍在风险集中的人数。随访后期人数较少，不能过度解释曲线尾部。', '', 'log-rank使用标准未加权双侧检验，另由各事件时间风险集、观察/期望事件及超几何方差独立计算，两终点结果一致。每组KM乘积限估计逐步核对。371位患者的30基因评分及分组从计数重新计算，数值一致。Cox比例风险假设检验OS p='+str(round(s.loc[s.endpoint.eq('OS'),'PH_test_p'].iloc[0],3))+'，PFI p='+str(round(s.loc[s.endpoint.eq('PFI'),'PH_test_p'].iloc[0],3))+'；未检测到显著违背，但不能证明假设绝对成立。','', '## 使用边界','', '此前单细胞分析未验证这30个基因对PGAM5相关状态的特异性；其中含通用巨噬细胞/免疫表达信号。这里的高低组是候选程序评分组，不是PGAM5⁺巨噬细胞高低浸润组。OS显著也不能反过来证明签名特异或PGAM5机制。阶段、肿瘤纯度、治疗及其他混杂因素未调整，且没有独立生存验证队列。本结果可用于形成待验证假设，不能直接写成PGAM5⁺巨噬细胞高浸润导致预后差。','', '## 下载与复现','', '- KM_OS.png/pdf、KM_PFI.png/pdf：KM曲线。','- survival_statistics.csv：log-rank、HR/CI、事件人数及BH校正。','- patient_scores_survival_join.csv、OS_analysis_patients.csv、PFI_analysis_patients.csv：患者级评分、分组及实际分析数据。','- selected_patient_31_gene_counts.csv、selected_patient_log2_CPM_plus1.csv、bulk_score_parameters.csv：评分输入和参数。','- independent_logrank_risk_sets.csv、KM_curve_values.csv、KM_numbers_at_risk.csv：统计与图的可复核数值。','- source_provenance.json、input_sha256.json、source_metadata：来源、镜像版本及数据校验。','', '复现：Python依赖见environment_versions.json。使用prepare.py取得的文件名，将NCBI原始矩阵及癌种样本表放入脚本目录；镜像来源的生存表已打包。依次运行prepare.py、analyze_survival.py、report_and_audit.py。prepare.py中的候选清单路径默认本云仓库路径，复现时改为同目录signature_30_genes.csv。大型泛癌原始矩阵不随包发布。source_metadata中保留镜像对象和来源脚本，第三方脚本仅作为来源证据，无须执行。']
(R/'README.md').write_text('\n'.join(lines)+'\n');print('Bulk score independent check:',err)
